 tb(['Group', 'Role and example'], ['<b>Farmers</b>', 'MSP, prices, debt relief: <b>Samyukt Kisan Morcha 2020-21</b> against three farm laws, <b>repealed in 2021</b>; SKM (Non-Political) and KMM <b>Dilli Chalo 2024</b>, legal MSP on <b>C2+50%</b>'], ['<b>Youth / Gen Z</b>', 'paper leaks, unemployment: Cockroach Janta Party 2026'], ['<b>Trade unions</b>', 'central unions\' strike 2025 (wages, Four Labour Codes); Noida workers April 2026, UP raised minimum wage ~21%'], ['<b>Environment</b>', 'Save Aarey 2019-22; Hasdeo Arand Bachao 2024'], ['<b>Professional</b>', 'IMA protests 2024 after RG Kar incident; demand for a Central Protection Act'], ['<b>Gig workers</b>', 'December 2025 strikes against 10-minute delivery targets; IFAT']),
 bx('ca', '<span class="tag">In the news · handout (verify)</span>Gen Z protests (2026) by the Cockroach Janta Party over exam irregularities; the handout links them to the Education Minister\'s July 2026 resignation. Unverified by me.'),
 sec('WESTERN vs INDIAN', 'r'),
 t('<b>Differences</b>', 'Western: "fourth organ"; Indian groups still minor in politics', 'India and Britain: target <b>cabinet and civil service</b>; USA: Congress and committees', 'Indian groups on caste, religion, region beat business bodies', 'US groups engage in foreign policy; Indian groups do not', w=26),
 sec('SIGNIFICANCE', 'g'),
 t('<b>Significance</b>', 'channel between citizens and government; wider participation (distrust of parties)', 'political socialisation; data for policy (FICCI, ASSOCHAM, CII)', 'counterbalance: no dominant force', 'informal face of politics; keep democracy alive between elections', '"legislatures behind legislatures"; reservoir of leaders (Kejriwal from the Lokpal movement)', 'check arbitrary power (farm laws); safety valve; consensus building', w=34),
 sec('TECHNIQUES, LOBBYING, BEST PRACTICES', 'b'),
 hub('TECHNIQUES', ['Lobbying (CII, FICCI)', 'PILs (CSE)', 'Media, digital drives', 'Mass protests', 'Report cards, social audit', 'Research, coalitions', 'Satyagraha, fasts', 'RTI exposés (MPLADS)'], 'EIGHT WAYS TO PRESSURE'),
 bx('bl', '<b>Best practices:</b> PAC report card, Bangalore · NCPRI and the RTI Act · #SaveAarey (2019) · CEHAT health advocacy · Anna Hazare\'s Jan Lokpal movement (2011).'),
 bx('pk', '<b>Lobbying:</b> named for business leaders in US Congress lobbies; formal contact with officials and ministers for favourable policy. <b>In India, neither legal nor illegal.</b> Problems: <b>paid lobbyists</b> (Nira Radia; Deepak Talwar), <b>legislators as lobbyists</b> (H.G. Mudgal disqualified from the provisional Parliament, Bombay Bullion Organisation), <b>bureaucrats</b> (serving or retired) tweaking rules. <b>Santhanam Committee 1962:</b> accredit lobbyists; no civil servant should meet business representatives unless accredited.'),
